export default {
  methods: {
    getColor(value: number) {
      const colorRatioDivider = 10;
      const colorRatio = value / colorRatioDivider;
      const divider = 100;
      const hue = ((1 - colorRatio) * divider).toString(10);
      return ['hsl(', hue, ',100%,70%)'].join('');
    },
  },
};
